def pip(poly,x,y):
 inside=False
 for i in range(len(poly)):
  x1,y1=poly[i]; x2,y2=poly[(i+1)%len(poly)]
  if (y1>y)!=(y2>y):
   xin=x1+(y-y1)*(x2-x1)/(y2-y1)
   if x<xin: inside=not inside
 return inside
