def on_segment(px,py,x1,y1,x2,y2,eps=1e-8):
 cross=(px-x1)*(y2-y1)-(py-y1)*(x2-x1)
 if abs(cross)>eps: return False
 return min(x1,x2)-eps<=px<=max(x1,x2)+eps and min(y1,y2)-eps<=py<=max(y1,y2)+eps
def pip_incl(poly,x,y):
 for i in range(len(poly)):
  if on_segment(x,y,*poly[i],*poly[(i+1)%len(poly)]): return True
 return pip(poly,x,y)
def square_incl(poly,d,r):
 corners=[(d,r-.5),(d+1,r-.5),(d-1,r+.5),(d,r+.5)]
 return all(pip_incl(poly,x,y) for x,y in corners)
